function save(){for(const [k,v] of Object.entries({nexa_page:state.page,nexa_name:state.name,nexa_avatar:state.avatar,nexa_favorites:JSON.stringify(state.favorites),nexa_history:JSON.stringify(state.history),nexa_playlists:JSON.stringify(state.playlists),nexa_folders:JSON.stringify(state.folders),nexa_theme:state.theme,nexa_accent:state.accent,nexa_autoplay:state.autoplay,nexa_animations:state.animations,nexa_visual_style:state.visualStyle,nexa_lang:state.lang,nexa_normal:state.normal,nexa_atmosphere:state.atmosphere,nexa_smart_queue:state.smartQueue,nexa_eq:JSON.stringify(state.eq),nexa_stats:JSON.stringify(state.stats),nexa_shuffle:shuffle}))localStorage.setItem(k,v);document.cookie='nexa_visual_style='+encodeURIComponent(state.visualStyle)+'; Max-Age=31536000; Path=/; SameSite=Lax'}
function esc(s){return String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function greeting(){const h=new Date().getHours();return h<12?'Buongiorno':h<18?'Buon pomeriggio':'Buonasera'}function fmt(s){if(!s)return'--:--';return `${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`}function allTracks(){return library}
function coverHTML(x,cls='cover'){return x.cover?`<div class="${cls}"><img src="${x.cover}" alt=""></div>`:`<div class="${cls}">♫</div>`}
function trackHTML(x,i){const fav=state.favorites.includes(i),playing=current===i;return `<div class="track${playing?' playing':''}" data-track="${i}">${coverHTML(x)}<div class="track-main"><div class="track-title">${esc(x.t)}</div><div class="track-sub">${esc(x.a)} · ${esc(x.al||'Locale')} · ${esc(x.d||'--:--')}</div>${playing?'<div class="now-playing">● IN RIPRODUZIONE</div>':''}</div><button class="play" data-play="${i}">${playing&&!audio().paused?'Ⅱ':'▶'}</button><button class="fav" data-fav="${i}">${fav?'♥':'♡'}</button><button class="delete" data-delete="${i}" aria-label="${T('delete')}">⌫</button></div>`}
function home(){const list=allTracks();return `<section class="hero"><div class="hero-content"><div class="eyebrow">NEXA PLAYER · MUSIC SYSTEM</div><h1>${greeting()}${state.name?', '+esc(state.name):''}</h1><div class="hero-atmo" hidden></div><canvas id="homeVisualizer" class="home-visualizer" aria-label="NEXA Visual Universe"></canvas></div></section><div class="visual-control"><div><div class="eyebrow">${T('visual')}</div><b>Scegli animazione</b></div><select id="visualStyle"><option value="bars">Spectrum Bars</option><option value="wave">Neon Wave</option><option value="orbit">Orbital Pulse</option><option value="rings">Pulse Rings</option><option value="particles">Star Particles</option></select></div><div class="hero-actions home-actions"><button class="primary" id="importBtn">${T('add')}</button><button id="cinemaBtn">◉ ${T('cinema')}</button><input id="fileInput" type="file" hidden multiple accept="audio/*,.mp3,.m4a,.aac,.wav,.flac,.ogg"></div><div class="quick"><div class="card"><div class="label">Brani locali</div><div class="value">${library.length}</div></div><div class="card color-preview-card"><div class="label">Colore NEXA</div><div class="value">Personalizzato</div><span class="quick-hint">Impostalo in Impostazioni</span></div><div class="card"><div class="label">Smart Queue</div><div class="value">${state.smartQueue?'ATTIVA':'OFF'}</div></div><div class="card remaining-card"><div class="label">Tempo rimanente</div><div class="value" id="homeRemaining">--:--</div></div></div><section class="content ecosystem-section"><div class="section-title"><h2>Ecosistema NEXA</h2><span>LOCAL CORE</span></div><div class="feature-grid"><div class="card feature" data-feature="dna">🧬<b>${T('dna')}</b><span>Music analysis · Energy · Rhythm · Mood</span></div><div class="card feature" data-feature="queue">🧠<b>${T('queue')}</b><span>Next-track intelligence</span></div><div class="card feature" data-feature="audio">🎚️<b>${T('audio')}</b><span>EQ · Bass · Presets</span></div><div class="card feature" data-feature="visual">🌌<b>${T('visual')}</b><span>Real-time music-reactive universe</span></div><div class="card feature" data-feature="insights">📊<b>${T('insights')}</b><span>Library intelligence · Local statistics</span></div><div class="card feature" data-feature="session">⏱️<b>${T('session')}</b><span>Listening Sessions</span></div><div class="card feature" data-feature="sleep">😴<b>${T('sleep')}</b><span>Smart Timer</span></div><div class="card feature" data-feature="cover">🎧<b>${T('cover')}</b><span>Automatic mix from your local library</span></div></div></section><section class="content song-section"><div class="section-title"><h2>${T('music')}</h2><span>${list.length} BRANI</span></div>${list.length?list.map(trackHTML).join(''):`<div class="empty">${T('empty')}<br><button class="primary" id="importBtn">${T('add')}</button></div>`}</section>` }
function listPage(title,list){return `<section class="content page-content"><div class="section-title"><h2>${title}</h2><span>${list.length} ELEMENTI</span></div><div class="search-wrap"><input id="trackSearch" placeholder="⌕ Cerca musica..."></div>${list.length?list.map(trackHTML).join(''):`<div class="empty">${T('empty')}<br><button class="primary" id="importBtn">${T('add')}</button></div>`}</section>`}
function profile(){return `<section class="content page-content"><div class="section-title"><h2>${T('profile')}</h2><span>LOCALE</span></div><div class="card profile-card"><label class="profile-avatar"><div class="avatar">${state.avatar?`<img src="${state.avatar}" alt="">`:(state.name?esc(state.name[0].toUpperCase()):'N')}</div><input id="avatarInput" type="file" hidden accept="image/*"></label><div class="label">DISPLAY NAME</div><div class="value">${state.name?esc(state.name):'Imposta il tuo nome'}</div><div class="actions"><button class="primary" id="editProfile">Modifica profilo</button></div></div></section>`}
function settings(){return `<section class="content page-content"><div class="section-title"><h2>${T('settings')}</h2><span>NEXA CORE</span></div><div class="settings-list"><label class="setting"><span><b>Colore sfondo NEXA</b><small>Scegli un colore: tutta l'interfaccia si adatta automaticamente</small></span><input id="accentSet" type="color" value="${esc(state.accent)}" aria-label="Colore sfondo"></label><label class="setting"><span><b>${T('theme')}</b><small>Modalità interfaccia</small></span><select id="themeSet"><option value="dark" ${state.theme==='dark'?'selected':''}>Scuro</option><option value="light" ${state.theme==='light'?'selected':''}>Chiaro</option></select></label><label class="setting"><span><b>${T('language')}</b><small>Italiano / English</small></span><select id="langSet"><option value="it" ${state.lang==='it'?'selected':''}>Italiano</option><option value="en" ${state.lang==='en'?'selected':''}>English</option></select></label><label class="setting"><span><b>${T('animations')}</b><small>Movimenti e transizioni NEXA</small></span><input id="animSet" type="checkbox" ${state.animations?'checked':''}></label><label class="setting"><span><b>${T('autoplay')}</b><small>Continua con il prossimo brano</small></span><input id="autoSet" type="checkbox" ${state.autoplay?'checked':''}></label><label class="setting"><span><b>${T('normal')}</b><small>Riduce differenze di volume</small></span><input id="normSet" type="checkbox" ${state.normal?'checked':''}></label><label class="setting"><span><b>${T('queue')}</b><small>Prossimo brano suggerito localmente</small></span><input id="queueSet" type="checkbox" ${state.smartQueue?'checked':''}></label><button class="setting-button" id="audioLabBtn">🎚️ ${T('audio')}</button><div class="color-presets"><b>Preset colore</b><div class="color-swatches">${['#526dff','#7c3aed','#00b8d9','#16a34a','#f59e0b','#ef4444','#ec4899','#ffffff'].map(c=>`<button type="button" class="color-swatch" data-color="${c}" style="--swatch:${c}" aria-label="${c}"></button>`).join('')}</div></div><button class="setting-button" id="sessionBtn">⏱️ ${T('session')}</button><button class="setting-button" id="insightsBtn">📊 ${T('insights')}</button><button class="setting-button" id="smartMixBtn">🎧 ${T('cover')}</button><button class="setting-button" id="sleepBtn">😴 ${T('sleep')}</button><button class="setting-button" id="scanBtn">↻ ${T('scan')}</button><button class="setting-button" id="resetStatsBtn">📊 Azzera statistiche ascolto</button><button class="setting-button" id="resetBtn">⌫ ${T('reset')}</button><div class="settings-note">NEXA Player mantiene musica, playlist, preferiti, profilo, statistiche e impostazioni sul dispositivo.</div></div></section>`}
function foldersPage(){return `<section class="content page-content"><div class="section-title"><h2>${T('folders')}</h2><span>${state.folders.length} CARTELLE</span></div><div class="toolbar"><button class="primary" id="newFolder">＋ Nuova cartella</button></div>${state.folders.length?state.folders.map((f,i)=>`<div class="folder card"><div class="folder-icon">▣</div><div><b>${esc(f.name)}</b><small>${f.tracks.length} brani</small></div><button data-folder-del="${i}" class="delete">⌫</button></div>`).join(''):`<div class="empty">Nessuna cartella creata.</div>`}</section>`}
let openPlaylist=-1;function playlistDetail(){const p=state.playlists[openPlaylist];if(!p){openPlaylist=-1;return playlistsPage()}const tracks=(p.tracks||[]).map(i=>allTracks()[i]).filter(Boolean);return `<section class="playlist-detail page-content"><button class="back-button" id="playlistBack">← Playlist</button><div class="playlist-header"><label class="playlist-cover-editor"><div class="playlist-cover">${p.cover?`<img src="${p.cover}" alt="">`:'♫'}</div><input id="playlistCoverInput" type="file" hidden accept="image/*"></label><div class="playlist-header-info"><div class="eyebrow">NEXA PLAYLIST</div><h1>${esc(p.name)}</h1><span>${tracks.length} brani</span></div></div><div class="playlist-actions"><button class="primary" id="playlistPlayAll">▶ ${T('play')}</button><button id="playlistShuffle">⇄ ${T('shuffle')}</button><button id="playlistAdd">＋ Aggiungi brani</button><button id="playlistRename">✎ ${T('rename')}</button></div><div class="playlist-tracks">${tracks.length?tracks.map((x,pi)=>`<div class="playlist-track-wrap">${trackHTML(x,allTracks().indexOf(x))}<div class="playlist-track-tools"><button data-pl-up="${pi}" ${pi===0?'disabled':''}>↑</button><button data-pl-down="${pi}" ${pi===tracks.length-1?'disabled':''}>↓</button><button data-pl-remove="${allTracks().indexOf(x)}">Rimuovi</button></div></div>`).join(''):`<div class="empty">Playlist vuota.</div>`}</div></section>`}
function playlistsPage(){return `<section class="content page-content"><div class="section-title"><h2>${T('playlists')}</h2><span>${state.playlists.length} PLAYLIST</span></div><div class="toolbar"><button class="primary" id="newPlaylist">＋ Nuova playlist</button></div>${state.playlists.length?state.playlists.map((p,i)=>`<div class="playlist-row card" data-playlist-open="${i}"><label class="playlist-thumb"><div>${p.cover?`<img src="${p.cover}" alt="">`:'♫'}</div><input data-cover-input="${i}" type="file" hidden accept="image/*"></label><div class="playlist-row-info"><b>${esc(p.name)}</b><small>${p.tracks.length} brani</small></div><button data-playlist-cover="${i}" class="icon-button">▣</button><button data-playlist-del="${i}" class="delete">⌫</button></div>`).join(''):`<div class="empty">Nessuna playlist creata.</div>`}</section>`}
function dna(x){const n=x?.name||x?.t||'';const ext=(x?.file?.type||x?.type||'').toLowerCase();let h=0;for(let i=0;i<n.length;i++)h=(h*31+n.charCodeAt(i))>>>0;const tempoHint=/dance|edm|techno|house|remix|club|rock|metal|punk/i.test(n)?72:/ambient|chill|sleep|piano|acoustic|classical|relax/i.test(n)?42:58;const energy=Math.max(25,Math.min(95,tempoHint+(h%21)-10));const rhythm=Math.max(25,Math.min(95,tempoHint+((h>>7)%25)-12));const mood=['Space','Night','Energy','Travel','Relax'][h%5];return {energy,rhythm,mood,type:ext}}
function dnaSummary(){if(!library.length)return'Ready';const e=Math.round(library.reduce((s,x)=>s+dna(x).energy,0)/library.length);return e>72?'Energy':e<48?'Relax':'Balanced'}
function modal(title,body){let m=document.querySelector('#featureModal');if(!m){m=document.createElement('div');m.id='featureModal';m.className='modal';document.body.appendChild(m)}m.innerHTML=`<div class="sheet"><div class="section-title"><h2>${title}</h2><button id="featureClose">×</button></div>${body}</div>`;m.classList.add('open');m.querySelector('#featureClose').onclick=()=>m.classList.remove('open');return m}
function openAudioLab(){const m=modal(T('audio'),`<div class="eq-grid">${['60Hz','250Hz','1kHz','4kHz','12kHz'].map((x,i)=>`<label>${x}<input class="eq" data-eq="${i}" type="range" min="-12" max="12" value="${state.eq[i]}"><b>${state.eq[i]} dB</b></label>`).join('')}</div><div class="preset-row"><button data-preset="flat">Flat</button><button data-preset="bass">Bass</button><button data-preset="vocal">Vocal</button><button data-preset="night">Night</button><button data-preset="reset">↺ Ripristina normale</button></div><div class="settings-note">Flat e Ripristina normale riportano l'equalizzatore a 0 dB.</div>`);const setSliders=p=>{state.eq=[...p];m.querySelectorAll('.eq').forEach((e,i)=>{e.value=p[i];e.nextElementSibling.textContent=p[i]+' dB'});save();applyEQ()};m.querySelectorAll('.eq').forEach(el=>el.oninput=e=>{const i=+e.target.dataset.eq;state.eq[i]=+e.target.value;e.target.nextElementSibling.textContent=state.eq[i]+' dB';save();applyEQ()});m.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const p={flat:[0,0,0,0,0],bass:[6,4,1,0,2],vocal:[-2,2,5,4,-1],night:[3,2,0,-2,-4],reset:[0,0,0,0,0]}[b.dataset.preset];if(p)setSliders(p)})}
function setupEQ(){if(!audioContext||!sourceNode||!analyser||eqNodes.length)return;const freqs=[60,250,1000,4000,12000];let prev=analyser;freqs.forEach((f,i)=>{const n=audioContext.createBiquadFilter();n.type='peaking';n.frequency.value=f;n.Q.value=1;n.gain.value=state.eq[i];prev.connect(n);eqNodes.push(n);prev=n});const gain=audioContext.createGain();gain.gain.value=1;prev.connect(gain);gain.connect(audioContext.destination)}function applyEQ(){if(eqNodes.length)eqNodes.forEach((n,i)=>n.gain.value=state.eq[i])}
function openAtmosphere(){const opts=['space','night','energy','rain','day','flight'];const m=modal(T('atmo'),`<div class="atmo-grid">${opts.map(x=>`<button data-atmo="${x}">✦ ${T(x)}</button>`).join('')}</div><button id="autoAtmo" class="setting-button">Auto Atmosphere: ${state.atmosphere==='auto'?'ON':'OFF'}</button>`);m.querySelectorAll('[data-atmo]').forEach(b=>b.onclick=()=>{state.atmosphere=b.dataset.atmo;save();applyAtmosphere();m.classList.remove('open');render()});const auto=m.querySelector('#autoAtmo');if(auto)auto.onclick=()=>{state.atmosphere=state.atmosphere==='auto'?'space':'auto';save();applyAtmosphere();m.classList.remove('open');render()}}
function applyAtmosphere(){}function applyAccent(){document.documentElement.style.setProperty('--nexa-accent',state.accent);document.documentElement.style.setProperty('--nexa-accent-soft',state.accent+'33');document.documentElement.style.setProperty('--nexa-accent-glow',state.accent+'55')}
function openDNA(){const rows=library.map(x=>{const d=dna(x);return `<div class="dna-row"><b>${esc(x.t)}</b><span>Energy ${d.energy}% · Rhythm ${d.rhythm}% · ${d.mood}</span></div>`}).join('');modal(T('dna'),`<div class="dna-summary"><b>Library DNA</b><strong>${dnaSummary()}</strong></div>${rows||'<div class="empty">Importa musica per analizzarla.</div>'}`)}
function openSmartMix(){const m=modal(T('cover'),'<div id="smartMixLive"></div>');const refresh=()=>{const now=Date.now();const candidates=library.filter((_,i)=>i!==current);const score=x=>{const plays=state.stats.byTrack[x.id||x.t]||0;const last=state.stats.lastPlayed?.[x.id||x.t]||0;const ageHours=last?Math.max(0,(now-last)/3600000):9999;const recency=Math.max(0,24-Math.min(24,ageHours));const discovery=plays===0?12:0;const artistPlays=state.stats.byArtist[x.a]||0;const artistBalance=artistPlays===0?8:Math.max(0,6-Math.min(6,artistPlays));return plays*10+recency*0.8+dna(x).energy*0.05+discovery+artistBalance};const ranked=[...candidates].sort((a,b)=>score(b)-score(a));const suggested=shuffle?[...ranked].sort(()=>Math.random()-.5).slice(0,10):ranked.slice(0,10);const box=m.querySelector('#smartMixLive');if(!box)return;box.innerHTML=`<p>Il mix impara dai tuoi ascolti, privilegia i brani recenti e inserisce anche qualche scoperta.</p><div class="queue-row"><b>Top ${suggested.length} brani</b><small>Classifica aggiornata automaticamente</small></div>${suggested.map((x,i)=>{const plays=state.stats.byTrack[x.id||x.t]||0;return `<div class="queue-row"><span>${i+1}</span><b>${esc(x.t)}</b><small>#${i+1} · ${plays} ${state.lang==='en'?'plays':'ascolti'} · ${esc(x.a)}</small></div>`}).join('')||'<div class="empty">Importa musica per creare il mix.</div>'}<button class="primary" id="smartMixPlay">⇄ Riproduzione casuale</button>`;const play=box.querySelector('#smartMixPlay');if(play)play.onclick=()=>{if(suggested.length){queue=suggested.map(x=>library.indexOf(x));for(let i=queue.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[queue[i],queue[j]]=[queue[j],queue[i]]}shuffle=true;save();playTrack(queue[0]);m.classList.remove('open')}}};refresh();m._refreshSmartMix=refresh}
function saveQueue(){queue=queue.filter(i=>Number.isInteger(i)&&i>=0&&i<library.length&&i!==current);localStorage.setItem('nexa_queue',JSON.stringify(queue))}function openQueue(){const m=modal(T('queue'),'<div class="queue-toggle">Coda di riproduzione · <b id="queueCount"></b></div><div id="queueList"></div><h3>Aggiungi alla coda</h3><div id="queueAddList"></div><div class="actions"><button id="clearQueue">Svuota coda</button></div>');const renderQueue=()=>{saveQueue();m.querySelector('#queueCount').textContent=queue.length+' '+(state.lang==='en'?'up next':'prossimi');m.querySelector('#queueList').innerHTML=queue.length?queue.map((idx,pos)=>{const x=library[idx];return x?'<div class="queue-row"><span>'+(pos+1)+'</span><b>'+esc(x.t)+'</b><small>'+esc(x.a)+'</small><button data-q-up="'+pos+'">↑</button><button data-q-down="'+pos+'">↓</button><button data-q-remove="'+pos+'">×</button></div>':''}).join(''):'<div class="empty">La coda è vuota.</div>';m.querySelector('#queueAddList').innerHTML=library.map((x,i)=>i!==current&&!queue.includes(i)?'<div class="queue-row"><b>'+esc(x.t)+'</b><small>'+esc(x.a)+'</small><button data-q-add="'+i+'">＋</button></div>':'').join('')||'<div class="empty">Nessun altro brano disponibile.</div>';m.querySelectorAll('[data-q-up]').forEach(b=>b.onclick=()=>{const i=+b.dataset.qUp;if(i>0){[queue[i-1],queue[i]]=[queue[i],queue[i-1]];renderQueue()}});m.querySelectorAll('[data-q-down]').forEach(b=>b.onclick=()=>{const i=+b.dataset.qDown;if(i<queue.length-1){[queue[i+1],queue[i]]=[queue[i],queue[i+1]];renderQueue()}});m.querySelectorAll('[data-q-remove]').forEach(b=>b.onclick=()=>{queue.splice(+b.dataset.qRemove,1);renderQueue()});m.querySelectorAll('[data-q-add]').forEach(b=>b.onclick=()=>{const i=+b.dataset.qAdd;if(i!==current&&!queue.includes(i)){queue.push(i);renderQueue()}})};m.querySelector('#clearQueue').onclick=()=>{queue=[];renderQueue()};renderQueue()}
function openReplay(){const by=Object.entries(state.stats.byArtist).sort((a,b)=>b[1]-a[1]).slice(0,5);modal(T('replay'),`<div class="replay-grid"><div><b>${state.stats.plays}</b><span>Play</span></div><div><b>${Math.round(state.stats.minutes)}</b><span>Minuti</span></div><div><b>${Object.keys(state.stats.byTrack).length}</b><span>Brani</span></div></div><h3>Artisti più ascoltati</h3>${by.map(x=>`<div class="dna-row"><b>${esc(x[0])}</b><span>${x[1]} ascolti</span></div>`).join('')||'<div class="empty">Inizia ad ascoltare.</div>'}`)}
function openInsights(){const artists=new Set(library.map(x=>x.a).filter(Boolean)).size;const albums=new Set(library.map(x=>x.al).filter(Boolean)).size;const total=library.reduce((n,x)=>n+parseDuration(x.d),0);const by=Object.entries(state.stats.byArtist).sort((a,b)=>b[1]-a[1]).slice(0,5);const played=Object.entries(state.stats.byTrack).sort((a,b)=>b[1]-a[1]).slice(0,5);modal(T('insights'),`<div class="replay-grid"><div><b>${library.length}</b><span>Brani locali</span></div><div><b>${fmt(total)}</b><span>Durata libreria</span></div><div><b>${artists}</b><span>Artisti</span></div><div><b>${albums}</b><span>Album</span></div></div><h3>Ascolti</h3><div class="dna-row"><b>${state.stats.plays}</b><span>riproduzioni · ${Math.round(state.stats.minutes)} minuti</span></div><h3>Artisti più ascoltati</h3>${by.map(x=>`<div class="dna-row"><b>${esc(x[0])}</b><span>${x[1]} ascolti</span></div>`).join('')||'<div class="empty">Inizia ad ascoltare per creare le statistiche.</div>'}<h3>Brani più ascoltati</h3>${played.map(x=>{const t=library.find(v=>(v.id||v.t)===x[0])||library.find(v=>v.t===x[0]);return t?`<div class="dna-row"><b>${esc(t.t)}</b><span>${x[1]} ascolti</span></div>`:''}).join('')||'<div class="empty">Nessun dato ancora.</div>'}`)}
function openSession(){const m=modal(T('session'),`<p>Costruisci una sessione locale scegliendo la durata.</p><div class="session-buttons">${[30,60,90,120].map(n=>`<button data-min="${n}">${n} min</button>`).join('')}</div><div id="sessionResult"></div>`);m.querySelectorAll('[data-min]').forEach(b=>b.onclick=()=>{const mins=+b.dataset.min;let total=0,count=0;const chosen=[];for(const x of library){const sec=parseDuration(x.d);if(total+sec<=mins*60){chosen.push(x);total+=sec;count++}}m.querySelector('#sessionResult').innerHTML=`<div class="card"><b>${mins} min</b><p>${count} brani · ${fmt(total)}</p><button class="primary" id="sessionPlay">▶ Avvia sessione</button></div>`;m.querySelector('#sessionPlay').onclick=()=>{if(chosen[0])playTrack(library.indexOf(chosen[0]));m.classList.remove('open')}})}
function parseDuration(d){const p=String(d).split(':').map(Number);return p.length===2?p[0]*60+p[1]:180}
function openSleep(){const m=modal(T('sleep'),`<div class="sleep-grid">${[5,10,15,30,45,60,90].map(n=>`<button data-sleep="${n}">${n} min</button>`).join('')}<button data-sleep="track">Fine brano</button><label class="custom-sleep">Personalizzato <input id="customSleep" type="number" min="1" max="600" value="20"> min <button data-sleep="custom">Avvia</button></label><button data-sleep="off">Disattiva</button></div><p id="sleepStatus">${sleepTimer?'Timer attivo':'Nessun timer attivo'}</p>`);m.querySelectorAll('[data-sleep]').forEach(b=>b.onclick=()=>{const v=b.dataset.sleep;if(sleepTimer){clearTimeout(sleepTimer);sleepTimer=null}if(v!=='off'&&v!=='track'&&v!=='custom'){sleepTimer=setTimeout(()=>{audio().pause();sleepTimer=null},+v*60000)}else if(v==='custom'){const n=Math.max(1,Math.min(600,+document.querySelector('#customSleep')?.value||20));sleepTimer=setTimeout(()=>{audio().pause();sleepTimer=null},n*60000)}else if(v==='track'){sleepTimer='track'}m.querySelector('#sleepStatus').textContent=v==='off'?'Disattivato':v==='track'?'Fine brano':`Attivo: ${v} min`})}
function openCoverStudio(){let saved=[];try{saved=JSON.parse(localStorage.getItem('nexa_cover_studio')||'[]')}catch(e){saved=[]}const m=modal(T('cover'),`<input id="coverFile" type="file" accept="image/*"><input id="coverText" placeholder="Titolo copertina"><div id="coverPreview" class="cover-studio-preview">NEXA</div><button class="primary" id="saveCover">Salva copertina</button><div class="settings-note">Le copertine vengono salvate sul dispositivo e restano disponibili dopo la chiusura dell'app.</div><div class="saved-covers">${saved.map((x,i)=>`<div class="saved-cover-row"><button type="button" class="saved-cover" data-saved-cover="${i}" title="${esc(x.name||'Copertina')}"><img src="${x.data}" alt=""><span>${esc(x.name||'NEXA Cover')}</span></button><button type="button" class="delete saved-cover-delete" data-delete-saved-cover="${i}" aria-label="Elimina copertina">⌫</button></div>`).join('')}</div>`);let data=saved[0]?.data||'';const preview=m.querySelector('#coverPreview');const text=m.querySelector('#coverText');const refreshPreview=()=>{preview.style.backgroundImage=data?`url(${data})`:'';preview.textContent=text.value.trim()||'NEXA'};m.querySelector('#coverFile').onchange=e=>{const f=e.target.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>{data=r.result;refreshPreview()};r.readAsDataURL(f)};text.oninput=refreshPreview;m.querySelectorAll('[data-saved-cover]').forEach(b=>b.onclick=()=>{const x=saved[+b.dataset.savedCover];if(x){data=x.data;text.value=x.name||'';refreshPreview()}});m.querySelectorAll('[data-delete-saved-cover]').forEach(b=>b.onclick=e=>{e.stopPropagation();const i=+b.dataset.deleteSavedCover;if(saved[i]&&confirm(state.lang==='en'?'Delete this saved cover?':'Eliminare questa copertina salvata?')){saved.splice(i,1);localStorage.setItem('nexa_cover_studio',JSON.stringify(saved));m.classList.remove('open');openCoverStudio()}});m.querySelector('#saveCover').onclick=()=>{if(!data){alert(state.lang==='en'?'Choose an image first.':'Scegli prima un’immagine.');return}const name=text.value.trim()||'NEXA Cover';const item={name,data,createdAt:Date.now()};saved=[item,...saved.filter(x=>x.data!==data)].slice(0,12);localStorage.setItem('nexa_cover_studio',JSON.stringify(saved));if(openPlaylist>=0&&state.playlists[openPlaylist]){state.playlists[openPlaylist].cover=data;save()}m.classList.remove('open');render()}}
function render(){state.visualStyle=getSavedVisualStyle();let html=state.page==='home'?home():state.page==='tracks'?listPage(T('tracks'),allTracks()):state.page==='favorites'?listPage(T('favorites'),state.favorites.map(i=>allTracks()[i]).filter(Boolean)):state.page==='profile'?profile():state.page==='settings'?settings():state.page==='playlists'?(openPlaylist>=0?playlistDetail():playlistsPage()):home();document.querySelector('#view').innerHTML=html;document.querySelectorAll('.nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));bind();applySettings();applyAccent();if(state.page==='home'){const vs=document.querySelector('#visualStyle');if(vs)vs.value=state.visualStyle;requestAnimationFrame(()=>requestAnimationFrame(()=>drawVisualizer()))}}
function bind(){const rh=document.querySelector('#returnHome');if(rh){rh.onclick=()=>{state.page='home';openPlaylist=-1;save();document.querySelectorAll('.modal.open').forEach(m=>m.classList.remove('open'));document.querySelector('#cinema')?.classList.remove('open');render();window.scrollTo({top:0,behavior:'smooth'})};rh.hidden=state.page==='home'}document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>playTrack(+b.dataset.play));document.querySelectorAll('[data-fav]').forEach(b=>b.onclick=()=>toggleFav(+b.dataset.fav));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>deleteTrack(+b.dataset.delete));const imp=document.querySelector('#importBtn');if(imp)imp.onclick=()=>document.querySelector('#fileInput')?.click();const fi=document.querySelector('#fileInput');if(fi)fi.onchange=e=>importFiles([...e.target.files]);const vs=document.querySelector('#visualStyle');if(vs)vs.onchange=e=>{state.visualStyle=validVisualStyles.includes(e.target.value)?e.target.value:'bars';save();drawVisualizer()};const cinema=document.querySelector('#cinemaBtn');if(cinema)cinema.onclick=openCinema;const homeAtmo=document.querySelector('#homeAtmo');if(homeAtmo)homeAtmo.remove();const np=document.querySelector('#newPlaylist');if(np)np.onclick=()=>{const n=prompt('Nome playlist');if(n?.trim()){state.playlists.push({name:n.trim(),tracks:[],cover:''});save();render()}};document.querySelectorAll('[data-playlist-open]').forEach(b=>b.onclick=e=>{if(e.target.closest('label,button'))return;openPlaylist=+b.dataset.playlistOpen;render()});document.querySelectorAll('[data-playlist-del]').forEach(b=>b.onclick=e=>{e.stopPropagation();if(confirm('Eliminare questa playlist?')){state.playlists.splice(+b.dataset.playlistDel,1);save();render()}});document.querySelectorAll('[data-playlist-cover]').forEach(b=>b.onclick=e=>{e.stopPropagation();document.querySelector(`[data-cover-input="${b.dataset.playlistCover}"]`)?.click()});document.querySelectorAll('[data-cover-input]').forEach(i=>i.onchange=e=>readImage(e.target,f=>{state.playlists[+i.dataset.coverInput].cover=f;save();render()}));const back=document.querySelector('#playlistBack');if(back)back.onclick=()=>{openPlaylist=-1;render()};const pc=document.querySelector('#playlistCoverInput');if(pc)pc.onchange=e=>readImage(e.target,f=>{state.playlists[openPlaylist].cover=f;save();render()});const pa=document.querySelector('#playlistAdd');if(pa)pa.onclick=()=>{if(openPlaylist<0)return;const choices=library.filter((_,i)=>!(state.playlists[openPlaylist].tracks||[]).includes(i)).map((x,i)=>`${i+1}. ${x.t}`).join('\n');const m=modal('Aggiungi brani alla playlist',`<p>Seleziona uno o più brani:</p><div class="playlist-picker">${library.map((x,i)=>({x,i})).filter(o=>!(state.playlists[openPlaylist].tracks||[]).includes(o.i)).map(o=>`<label class="playlist-picker-row"><input type="checkbox" value="${o.i}"><span>${coverHTML(o.x,'playlist-picker-cover')}<span><b>${esc(o.x.t)}</b><small>${esc(o.x.a)} · ${esc(o.x.d||'--:--')}</small></span></span></label>`).join('')||'<div class="empty">Tutti i brani sono già nella playlist.</div>'}</div><button class="primary" id="confirmPlaylistAdd">Aggiungi selezionati</button>`);const ok=m.querySelector('#confirmPlaylistAdd');if(ok)ok.onclick=()=>{m.querySelectorAll('.playlist-picker-row input:checked').forEach(c=>{const i=+c.value;if(!state.playlists[openPlaylist].tracks.includes(i))state.playlists[openPlaylist].tracks.push(i)});save();m.classList.remove('open');render()}};document.querySelectorAll('[data-pl-up]').forEach(b=>b.onclick=()=>{const p=state.playlists[openPlaylist],i=+b.dataset.plUp;if(p&&i>0){[p.tracks[i-1],p.tracks[i]]=[p.tracks[i],p.tracks[i-1]];save();render()}});document.querySelectorAll('[data-pl-down]').forEach(b=>b.onclick=()=>{const p=state.playlists[openPlaylist],i=+b.dataset.plDown;if(p&&i<p.tracks.length-1){[p.tracks[i+1],p.tracks[i]]=[p.tracks[i],p.tracks[i+1]];save();render()}});document.querySelectorAll('[data-pl-remove]').forEach(b=>b.onclick=()=>{const p=state.playlists[openPlaylist],i=+b.dataset.plRemove;if(p){p.tracks=p.tracks.filter(x=>x!==i);save();render()}});const pall=document.querySelector('#playlistPlayAll');if(pall)pall.onclick=()=>{const i=state.playlists[openPlaylist]?.tracks?.find(i=>library[i]);if(i!=null)playTrack(i)};const psh=document.querySelector('#playlistShuffle');if(psh)psh.onclick=()=>{const a=(state.playlists[openPlaylist]?.tracks||[]).filter(i=>library[i]);if(a.length)playTrack(a[Math.floor(Math.random()*a.length)])};const pr=document.querySelector('#playlistRename');if(pr)pr.onclick=()=>{const n=prompt('Nuovo nome',state.playlists[openPlaylist]?.name);if(n?.trim()){state.playlists[openPlaylist].name=n.trim();save();render()}};const ep=document.querySelector('#editProfile');if(ep)ep.onclick=openProfile;const av=document.querySelector('#avatarInput');if(av)av.onchange=e=>readImage(e.target,f=>{state.avatar=f;save();render()});const accent=document.querySelector('#accentSet');if(accent)accent.oninput=e=>{state.accent=e.target.value;save();applyAccent()};document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.accent=b.dataset.color;save();applyAccent();const c=document.querySelector('#accentSet');if(c)c.value=state.accent});const theme=document.querySelector('#themeSet');if(theme)theme.onchange=e=>{state.theme=e.target.value;save();applySettings()};const lang=document.querySelector('#langSet');if(lang)lang.onchange=e=>{state.lang=e.target.value;save();render()};const an=document.querySelector('#animSet');if(an)an.onchange=e=>{state.animations=e.target.checked;save();applySettings()};const au=document.querySelector('#autoSet');if(au)au.onchange=e=>{state.autoplay=e.target.checked;save()};const no=document.querySelector('#normSet');if(no)no.onchange=e=>{state.normal=e.target.checked;save()};const qs=document.querySelector('#queueSet');if(qs)qs.onchange=e=>{state.smartQueue=e.target.checked;save()};const scan=document.querySelector('#scanBtn');if(scan)scan.onclick=async()=>{await loadLibrary();alert(state.lang==='en'?'Library refreshed.':'Libreria aggiornata.')};const resetStats=document.querySelector('#resetStatsBtn');if(resetStats)resetStats.onclick=()=>{if(confirm(state.lang==='en'?'Reset listening statistics?':'Azzerare tutte le statistiche di ascolto?')){state.stats={minutes:0,plays:0,byArtist:{},byTrack:{},lastPlayed:{}};save();render()}};const mixLabel=document.querySelector('#shuffleBtn');if(mixLabel){mixLabel.classList.toggle('primary',shuffle);mixLabel.setAttribute('aria-pressed',shuffle?'true':'false');mixLabel.title=shuffle?(state.lang==='en'?'Random playback ON':'Riproduzione casuale ATTIVA'):(state.lang==='en'?'Random playback OFF':'Riproduzione casuale DISATTIVA')};const reset=document.querySelector('#resetBtn');if(reset)reset.onclick=()=>{if(confirm('Cancellare tutti i dati locali?')){localStorage.clear();location.reload()}};const al=document.querySelector('#audioLabBtn');if(al)al.onclick=openAudioLab;const at=document.querySelector('#atmoBtn');if(at)at.remove();const se=document.querySelector('#sessionBtn');if(se)se.onclick=openSession;const re=document.querySelector('#insightsBtn');if(re)re.onclick=openInsights;const sm=document.querySelector('#smartMixBtn');if(sm)sm.onclick=openSmartMix;const sl=document.querySelector('#sleepBtn');if(sl)sl.onclick=openSleep;document.querySelectorAll('[data-feature="dna"]').forEach(b=>b.onclick=openDNA);document.querySelectorAll('[data-feature="queue"]').forEach(b=>b.onclick=openQueue);document.querySelectorAll('[data-feature="audio"]').forEach(b=>b.onclick=openAudioLab);document.querySelectorAll('[data-feature="visual"]').forEach(b=>b.onclick=()=>{const vs=document.querySelector('#visualStyle');if(vs){vs.scrollIntoView({behavior:'smooth',block:'center'});vs.focus()}});document.querySelectorAll('[data-feature="session"]').forEach(b=>b.onclick=openSession);document.querySelectorAll('[data-feature="insights"]').forEach(b=>b.onclick=openInsights);document.querySelectorAll('[data-feature="sleep"]').forEach(b=>b.onclick=openSleep);document.querySelectorAll('[data-feature="cover"]').forEach(b=>b.onclick=openSmartMix);document.querySelectorAll('.feature').forEach(b=>{b.setAttribute('role','button');b.setAttribute('tabindex','0');b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();b.click()}}});const progress=document.querySelector('#progress');if(progress)progress.oninput=()=>{if(audio().duration)audio().currentTime=audio().duration*(+progress.value/100)};const search=document.querySelector('#trackSearch');if(search)search.oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.track').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'flex':'none')}}
function readImage(input,cb){const f=input.files?.[0];if(!f)return;const r=new FileReader();r.onload=()=>cb(r.result);r.readAsDataURL(f)}
function openProfile(){const m=document.querySelector('#modal');m.classList.add('open');document.querySelector('#nameInput').value=state.name;document.querySelector('#nameInput').focus()}function closeModal(){document.querySelector('#modal').classList.remove('open')}function saveProfile(){state.name=document.querySelector('#nameInput').value.trim();save();closeModal();render()}
const DB='nexa_player_db',STORE='tracks';function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB,1);r.onupgradeneeded=()=>r.result.createObjectStore(STORE,{keyPath:'id'});r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})}async function loadLibrary(){try{const db=await openDB();const rows=await new Promise((res,rej)=>{const q=db.transaction(STORE).objectStore(STORE).getAll();q.onsuccess=()=>res(q.result);q.onerror=()=>rej(q.error)});library=rows.map(x=>({...x,url:URL.createObjectURL(x.blob)}));render()}catch(e){library=[];render()}}
async function storeTrack(x){try{const db=await openDB();db.transaction(STORE,'readwrite').objectStore(STORE).put(x)}catch(e){}}
async function importFiles(files){for(const file of files){if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|aac|wav|flac|ogg)$/i.test(file.name))continue;const url=URL.createObjectURL(file);const probe=new Audio(url);const duration=await new Promise(resolve=>{let done=false;const finish=()=>{if(!done){done=true;resolve(Number.isFinite(probe.duration)?probe.duration:0)}};probe.onloadedmetadata=finish;probe.onerror=finish;setTimeout(finish,1200)});const base=file.name.replace(/\.[^.]+$/,'');const x={id:crypto.randomUUID(),t:base,a:'Artista sconosciuto',al:'Libreria locale',d:fmt(duration),name:file.name,blob:file,url,cover:''};library.push(x);await storeTrack(x)}render()}
function startAudioPlayback(){const a=audio();if(!a||!a.src||playLock)return;playLock=true;try{setupAudio();if(audioContext?.state==='suspended')audioContext.resume().catch(()=>{});const p=a.play();if(p&&typeof p.then==='function'){p.catch(e=>{console.warn('NEXA playback:',e)}).finally(()=>{playLock=false})}else playLock=false}catch(e){playLock=false;console.warn('NEXA playback:',e)}}function playTrack(i){const x=library[i];if(!x)return;objectUrl=x.url;current=i;const a=audio();a.pause();a.src='';a.load();a.src=x.url;a.load();try{startAudioPlayback()}catch(e){console.warn('NEXA playback:',e);updatePlayer(x);return}state.history=[i,...state.history.filter(v=>v!==i)].slice(0,50);state.stats.plays++;state.stats.minutes+=parseDuration(x.d)/60;state.stats.byArtist[x.a]=(state.stats.byArtist[x.a]||0)+1;state.stats.byTrack[x.id||x.t]=(state.stats.byTrack[x.id||x.t]||0)+1;state.stats.lastPlayed=state.stats.lastPlayed||{};state.stats.lastPlayed[x.id||x.t]=Date.now();save();updatePlayer(x);const mixModal=document.querySelector('#featureModal');if(mixModal?._refreshSmartMix)mixModal._refreshSmartMix();if('mediaSession' in navigator){navigator.mediaSession.metadata=new MediaMetadata({title:x.t,artist:x.a,album:x.al||'NEXA Player'});navigator.mediaSession.playbackState='playing'}}
function updatePlayer(x){const p=document.querySelector('#player');if(!p)return;p.classList.add('show');const title=x?.t||'Nessun brano',artist=x?.a||'Seleziona una canzone';const c=document.querySelector('#playerCover');if(c)c.innerHTML=x?.cover?`<img src="${x.cover}" alt="">`:'♫';document.querySelector('#playerTitle').textContent=title;document.querySelector('#playerArtist').textContent=artist;const topTitle=document.querySelector('#topNowTitle');if(topTitle)topTitle.textContent=title;document.querySelector('#playerPlay').textContent=audio().paused?'▶':'Ⅱ';document.querySelectorAll('.track').forEach(r=>{const active=+r.dataset.track===current;r.classList.toggle('playing',active);const b=r.querySelector('.play');if(b)b.textContent=active&&!audio().paused?'Ⅱ':'▶'})}
function toggleFav(i){state.favorites=state.favorites.includes(i)?state.favorites.filter(x=>x!==i):[...state.favorites,i];save();render()}function deleteTrack(i){const x=library[i];if(!x||!confirm(`${T('delete')} "${x.t}"?`))return;if(current===i){audio().pause();audio().removeAttribute('src');current=-1}queue=queue.filter(v=>v!==i).map(v=>v>i?v-1:v);saveQueue();if(x.url)URL.revokeObjectURL(x.url);library.splice(i,1);openDB().then(db=>db.transaction(STORE,'readwrite').objectStore(STORE).delete(x.id)).catch(()=>{});state.favorites=state.favorites.filter(v=>v!==i).map(v=>v>i?v-1:v);state.history=state.history.filter(v=>v!==i).map(v=>v>i?v-1:v);state.playlists.forEach(p=>p.tracks=(p.tracks||[]).filter(v=>v!==i).map(v=>v>i?v-1:v));save();render()}
function stepTrack(dir){if(!library.length)return;let n;if(dir>0&&queue.length){n=queue.shift();saveQueue()}else if(shuffle){const recent=new Set((state.history||[]).slice(0,Math.min(8,library.length)));const cand=library.map((_,i)=>i).filter(i=>i!==current);const fresh=cand.filter(i=>!recent.has(i));const pool=fresh.length?fresh:cand;n=pool.length?pool[Math.floor(Math.random()*pool.length)]:current}else if(state.smartQueue&&dir>0){const cand=library.map((x,i)=>({i,e:dna(x).energy})).filter(x=>x.i!==current).sort((a,b)=>Math.abs(a.e-dna(library[current]||{}).energy)-Math.abs(b.e-dna(library[current]||{}).energy));n=cand[0]?.i??((current+dir+library.length)%library.length)}else n=(current+dir+library.length)%library.length;playTrack(n)}
function setupAudio(){const a=audio();if(!a)return false;try{if(audioContext?.state==='closed'){audioContext=null;sourceNode=null;analyser=null;eqNodes=[]}if(!audioContext){const C=window.AudioContext||window.webkitAudioContext;if(!C)return false;audioContext=new C();sourceNode=audioContext.createMediaElementSource(a);analyser=audioContext.createAnalyser();analyser.fftSize=256;analyser.smoothingTimeConstant=.82;sourceNode.connect(analyser);setupEQ()}if(audioContext.state==='suspended')audioContext.resume().catch(()=>{});return true}catch(e){console.warn('NEXA audio engine:',e);return false}}
function drawVisualizer(){const c=document.querySelector('#homeVisualizer')||document.querySelector('#visualizer');if(!c)return;if(animFrame)cancelAnimationFrame(animFrame);const g=c.getContext('2d');if(!g)return;let data=null;let cw=0,ch=0;function frame(t){const home=document.querySelector('#homeVisualizer'),cinema=document.querySelector('#cinema.open');if(!home&&!cinema){animFrame=null;return}animFrame=requestAnimationFrame(frame);const dpr=Math.min(devicePixelRatio||1,2),r=c.getBoundingClientRect(),nw=Math.max(1,Math.floor(r.width*dpr)),nh=Math.max(1,Math.floor(r.height*dpr));if(nw!==cw||nh!==ch){cw=nw;ch=nh;c.width=cw;c.height=ch}if(analyser){if(!data||data.length!==analyser.frequencyBinCount)data=new Uint8Array(analyser.frequencyBinCount);analyser.getByteFrequencyData(data)}g.clearRect(0,0,cw,ch);const storedStyle=localStorage.getItem('nexa_visual_style'),style=validVisualStyles.includes(storedStyle)?storedStyle:(validVisualStyles.includes(state.visualStyle)?state.visualStyle:'bars');state.visualStyle=style;const cx=cw/2,cy=ch/2;g.lineWidth=2*dpr;g.strokeStyle='rgba(125,150,255,.9)';g.fillStyle='rgba(125,150,255,.9)';if(style==='wave'){g.beginPath();for(let x=0;x<=cw;x+=4*dpr){const idx=Math.min((data?.length||1)-1,Math.floor(x/cw*(data?.length||64))),v=data?data[idx]/255:.35,y=cy+Math.sin(x*.018+t*.003)*(18*dpr+v*70*dpr);x===0?g.moveTo(x,y):g.lineTo(x,y)}g.stroke()}else if(style==='orbit'){const pulse=data?data[8]/255:.35;g.beginPath();g.arc(cx,cy,(35+pulse*55)*dpr,0,Math.PI*2);g.stroke();for(let i=0;i<8;i++){const a=t*.001*(i%2?-.7:.7)+i*Math.PI/4,rr=(65+(data?data[i*3]/255:0)*45)*dpr;g.beginPath();g.arc(cx+Math.cos(a)*rr,cy+Math.sin(a)*rr,5*dpr,0,Math.PI*2);g.fill()}}else if(style==='rings'){const pulse=data?data[2]/255:.3;for(let k=0;k<4;k++){g.globalAlpha=.8-k*.15;g.beginPath();g.arc(cx,cy,(25+k*28+pulse*22)*dpr,0,Math.PI*2);g.stroke()}g.globalAlpha=1}else if(style==='particles'){for(let i=0;i<70;i++){const idx=i%(data?.length||64),v=data?data[idx]/255:.25,a=i*2.4+t*.00035*(i%3+1),rr=(20+(i*17%100)+v*40)*dpr,x=cx+Math.cos(a)*rr,y=cy+Math.sin(a)*rr;g.globalAlpha=.25+v*.7;g.beginPath();g.arc(x,y,Math.max(1.5,v*4)*dpr,0,Math.PI*2);g.fill()}g.globalAlpha=1}else{const bars=data?Math.min(data.length,64):64,w=cw/bars;for(let i=0;i<bars;i++){const v=data?data[i]/255:Math.max(.08,.16+.13*(.5+.5*Math.sin(i*2.71))*(.72+.28*Math.sin(t*.0017+i*.47)));const h=Math.max(3*dpr,v*ch*.78);g.fillRect(i*w,ch-h,Math.max(2*dpr,w*.62),h)}}}frame(performance.now())}
function openCinema(){document.querySelector('#cinema').classList.add('open');document.querySelector('#cinemaTitle').textContent=library[current]?.t||'NEXA MUSIC CINEMA';setupAudio();drawVisualizer()}function applySettings(){document.body.classList.toggle('light',state.theme==='light');document.body.classList.toggle('no-animations',!state.animations)}
document.addEventListener('click',e=>{const b=e.target.closest('.nav button');if(!b)return;state.page=b.dataset.page;openPlaylist=-1;save();render()});
document.addEventListener('DOMContentLoaded',()=>{render();loadLibrary();const p=document.querySelector('#player');if(p)p.addEventListener('click',e=>{if(e.target.closest('.player-btn,.progress'))return;if(current>=0)openCinema()});document.querySelector('#saveName').onclick=saveProfile;document.querySelector('#closeModal').onclick=closeModal;document.querySelector('#playerPlay').onclick=()=>{const a=audio();if(!a.src)return;if(a.paused)startAudioPlayback();else a.pause();updatePlayer(library[current]||{})};document.querySelector('#prevBtn').onclick=()=>stepTrack(-1);document.querySelector('#nextBtn').onclick=()=>stepTrack(1);document.querySelector('#shuffleBtn').onclick=e=>{shuffle=!shuffle;save();e.currentTarget.classList.toggle('primary',shuffle)};document.querySelector('#shuffleBtn').classList.toggle('primary',shuffle);const qb=document.querySelector('#queueBtn');if(qb)qb.onclick=openQueue;document.querySelector('#repeatBtn').onclick=e=>{repeat=!repeat;e.currentTarget.classList.toggle('primary',repeat)};document.querySelector('#cinemaOpen').onclick=openCinema;document.querySelector('#cinemaPlay').onclick=()=>document.querySelector('#playerPlay').click();document.querySelector('#cinemaExit').onclick=()=>{document.querySelector('#cinema').classList.remove('open');drawVisualizer()};audio().addEventListener('play',()=>{updatePlayer(library[current]||{});if('mediaSession'in navigator)navigator.mediaSession.playbackState='playing'});audio().addEventListener('pause',()=>{updatePlayer(library[current]||{});if('mediaSession'in navigator)navigator.mediaSession.playbackState='paused'});audio().addEventListener('error',()=>{console.warn('NEXA audio error',audio().error);if(current>=0&&audio().src&&recoveryTimer===null){recoveryTimer=setTimeout(()=>{recoveryTimer=null;const a=audio();if(a.error&&current>=0){const src=library[current]?.url;if(src){a.src=src;a.load();startAudioPlayback()}}},350)}});audio().addEventListener('stalled',()=>{if(recoveryTimer===null&&current>=0&&audio().src){recoveryTimer=setTimeout(()=>{recoveryTimer=null;const a=audio();if(a.readyState<3&&current>=0){a.load();startAudioPlayback()}},1200)}});audio().addEventListener('timeupdate',()=>{const a=audio();const p=document.querySelector('#progress');if(p&&a.duration)p.value=a.currentTime/a.duration*100;const r=document.querySelector('#homeRemaining');if(r&&Number.isFinite(a.duration)){const left=Math.max(0,a.duration-a.currentTime);r.textContent=fmt(left)}});audio().addEventListener('ended',()=>{if(sleepTimer==='track'){audio().pause();sleepTimer=null;return}if(repeat&&current>=0)playTrack(current);else if(state.autoplay)stepTrack(1)});audio().addEventListener('loadedmetadata',()=>{if('mediaSession'in navigator)navigator.mediaSession.setPositionState?.({duration:audio().duration,playbackRate:audio().playbackRate,position:audio().currentTime})});if('mediaSession'in navigator){navigator.mediaSession.setActionHandler('play',()=>{startAudioPlayback()});navigator.mediaSession.setActionHandler('pause',()=>audio().pause());navigator.mediaSession.setActionHandler('previoustrack',()=>stepTrack(-1));navigator.mediaSession.setActionHandler('nexttrack',()=>stepTrack(1))}});